    expect(output).toContain("[worker sess-abc]\nI am streaming");
    expect(output).toContain("\nNext line");
    expect((output.match(/\[worker sess-abc\]/g) ?? []).length).toBe(1);

    runPromise.catch(() => {/* ignore */});

