  const hasGlobal = typeof gws !== "undefined";
  const err = new Error();
  console.error("[debug-ws] hasGlobal:", hasGlobal, "gws name:", gws?.name, "stack:", err.stack?.split("\n").slice(1,4).join(" <- "));
  return hasGlobal ? gws : WsFallback;
}
