  const hasGlobal = typeof gws !== "undefined";
  console.error(\`[ws-ctor] globalThis.WebSocket name=\${gws?.name} hasGlobal=\${hasGlobal} isFallback=\${gws === WsFallback}\`);
  return hasGlobal ? gws : WsFallback;
}
