describe("AC-11: JSON mode suppresses streaming output", () => {
  let testDir: string;

  beforeEach(() => {
    testDir = require("node:fs").mkdtempSync(require("node:path").join(require("node:os").tmpdir(), "kspec-agent-stream-json-"));
