      expect((output.match(/\[worker-a sess-a\]/g) ?? []).length).toBe(2);
      expect((output.match(/\[worker-b sess-b\]/g) ?? []).length).toBe(1);
    }

    runPromise.catch(() => {/* ignore */});
  });
});

