const MOCK_ACP = path.join(__dirname, "mocks", "acp-mock.js");

function registerMockAdapter(): void {
  registerAdapter("mock-acp", {
    command: "node",
    args: [MOCK_ACP],
    env: { MOCK_ACP_PROJECT_DIR: process.cwd() },
    description: "Mock ACP adapter for testing",
  });
