    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.yaml"),
      YAML.stringify({ kynetic: "1", title: "Test" }),
    );
    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.meta.yaml"),
      YAML.stringify({
        kynetic_meta: "1.0",
        agents: [{
          _ulid: agent._ulid,
